bad = 0
for f, old, new, pkg, test, label in M:
    p = Path(f); src = p.read_text()
    if src.count(old) != 1:
        print(f"??    {label}: pattern not found once in {f}"); bad += 1; continue
    p.write_text(src.replace(old, new))
    try:
        if pkg == "extension":
            # The extension's rules live in JavaScript: node --test, by name.
            r = subprocess.run(["node", "--test", "--test-name-pattern=^" + test + "$", "lib.test.js", "manifest.test.js"], cwd="../extension", capture_output=True, text=True)
            r.stdout += "FAIL" if r.returncode != 0 else ""
        else:
            r = subprocess.run(["go", "test", "./" + pkg + "/", "-run", "^" + test + "$", "-count=1", "-timeout=2m"], capture_output=True, text=True)
    finally:
        p.write_text(src)
    if "[build failed]" in r.stdout + r.stderr or "[setup failed]" in r.stdout + r.stderr:
        print(f"BUILD   {label} -> {test} (the mutant does not build or go vet refuses it)"); bad += 1
    elif "no tests to run" in r.stdout + r.stderr:
        print(f"NOTEST  {label} -> {test} (no test has this name)"); bad += 1
    elif r.returncode != 0 and ("FAIL" in r.stdout or "FAIL" in r.stderr):
        print(f"KILLED  {label} -> {test}")
    else:
        print(f"ALIVE   {label} -> {test} (test passed with the mutation)"); bad += 1
print("alive or build:", bad)
sys.exit(1 if bad else 0)
